import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"謙","description":"焦氏易林注 - 謙","frontmatter":{"title":"謙","description":"焦氏易林注 - 謙"},"headers":[],"relativePath":"zh/classics/jiaoyilin/015.md","filePath":"zh/classics/jiaoyilin/015.md"}'),l={name:"zh/classics/jiaoyilin/015.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="謙" tabindex="-1">謙 <a class="header-anchor" href="#謙" aria-label="Permalink to “謙”">​</a></h1><h3 id="謙-1" tabindex="-1">謙 <a class="header-anchor" href="#謙-1" aria-label="Permalink to “謙”">​</a></h3><h3 id="謙之乾" tabindex="-1">謙之乾 <a class="header-anchor" href="#謙之乾" aria-label="Permalink to “謙之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>喋囁噱嚾，昧冥相摶。多言少實，語無成事。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此取遇卦《謙》象。註解詳捲九《明夷》之《豫》。《豫》與《謙》同象。喋，汲古作嗛，依宋元本。噱嚾，宋元本訛處曜，汲古作噱嚶。摶，宋元作待，汲古訛持，依汲古，《中孚》之《升》校有詳說。</p><h3 id="謙之坤" tabindex="-1">謙之坤 <a class="header-anchor" href="#謙之坤" aria-label="Permalink to “謙之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>北辰紫宮，衣冠立中。含和建德，常受大福。鉛刀攻玉，堅不可得。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《觀》。多下二句。此亦用《謙》象。艮為刀、為金，坤柔故曰鉛刀。震為玉，艮為堅。○艮為刀、為金證。</p><h3 id="謙之屯" tabindex="-1">謙之屯 <a class="header-anchor" href="#謙之屯" aria-label="Permalink to “謙之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>東壁餘光，數暗不明。主母嫉妬，亂我事業。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震為東，艮為壁，故曰東壁。艮又為火、為光明，坎為暗，故不明。坤為母，震為主，故曰主母。坎為嫉妬，坤為亂、為事業。《列女傳》：&quot;貧婦徐吾與鄰婦會燭，夜續燭，數不給，鄰婦欲擯之，吾曰，一室之內，增一人，燭不為暗，少一人，不為明，何愛東壁之餘光乎？&quot;林用其事。</p><h3 id="謙之蒙" tabindex="-1">謙之蒙 <a class="header-anchor" href="#謙之蒙" aria-label="Permalink to “謙之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>下背其上，盜明相讓。子嬰兩頭，陳破其墟。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坤為下，艮為背、為上、為明，坎為盜，震為言，正反震相對故曰相讓。震子、震嬰。坎為首，坤數二，故曰兩頭。震為陳，坎為破，坤為墟。兩頭於象甚合，其義未詳，疑為面縛之訛。○相讓，從宋元本，汲古作其，非。讓，責也。子嬰，從汲古，宋元本作嬰子，非。陳，陳涉也，言陳涉亡秦滅子嬰也。</p><h3 id="謙之需" tabindex="-1">謙之需 <a class="header-anchor" href="#謙之需" aria-label="Permalink to “謙之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>鳳生會稽，稍巨能飛。翱翔桂林，為眾鳥雄。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>離文為鳳，伏艮為山。會稽，山名。艮陽在上為飛、為翱翔、為林、為鳥，坤為眾。全用伏。○能飛，從宋本，元本作飛翔，非。巨，汲古作其，依宋元本。</p><h3 id="謙之訟" tabindex="-1">謙之訟 <a class="header-anchor" href="#謙之訟" aria-label="Permalink to “謙之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>鑿井求玉，非和氏寶。名困身辱，勞無所得。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>坎陷為井，乾為玉、為寶，坎為和，伏坤為身、為辱。艮為名，艮覆故名困。坎為勞。○非和氏寶，依宋本及汲古，元本作&quot;非卞氏室&quot;，非。</p><h3 id="謙之師" tabindex="-1">謙之師 <a class="header-anchor" href="#謙之師" aria-label="Permalink to “謙之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>邦桀載殳，道至東萊。百僚具舉，君王嘉喜。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坤為邦、為惡，故曰桀。艮為殳，兵器也。《詩衛風》：&quot;邦之桀兮，伯也執殳&quot;。震為大塗、為陵，震東故曰東萊。東萊，山名。坤為百，艮為官，互震為君王、為嘉喜。○邦桀，從宋元本，汲古訛拜桀。殳，從陳本，元本、宋本、汲古皆訛役。道，從宋元本，汲古作送。《漢書郊祀志》：&quot;東萊山，黃帝所常游&quot;，林詞似指此事。</p><h3 id="謙之比" tabindex="-1">謙之比 <a class="header-anchor" href="#謙之比" aria-label="Permalink to “謙之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>安息康居，異國穹廬。非吾邦域，使伯憂戚。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《屯》。○穹、戚，依汲古，宋元本作同、作惑。</p><h3 id="謙之小畜" tabindex="-1">謙之小畜 <a class="header-anchor" href="#謙之小畜" aria-label="Permalink to “謙之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>江河淮海，天之都市。商人受福，國家富有。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《乾》。</p><h3 id="謙之履" tabindex="-1">謙之履 <a class="header-anchor" href="#謙之履" aria-label="Permalink to “謙之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>同本異業，樂仁尚德。東鄰慕義，來興吾國。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。震為木，正反震而以三爻為本，故曰同本異葉。震為仁德、為樂、為東、為興，坤為吾、為國。○鄰，依宋元本，汲古訛林。</p><h3 id="謙之泰" tabindex="-1">謙之泰 <a class="header-anchor" href="#謙之泰" aria-label="Permalink to “謙之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>白鶴銜珠，夜室為明。懷我德音，身受光榮。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>震為白、為鶴、為珠，兌為口，故曰銜。坤為夜、為室，震為明、為音，坤為懷、為我、為身，乾為光榮。《搜神記》：&quot;噲參行遇黔鶴，為弋人射傷，收養之，放去，一夜，雌雄各銜一明月珠來以報參&quot;。○室，宋元作食，從汲古。為，從宋元，汲古作反。我，元本作吾，從宋本、汲古。</p><h3 id="謙之否" tabindex="-1">謙之否 <a class="header-anchor" href="#謙之否" aria-label="Permalink to “謙之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>踐履危難，脫厄去患。入福喜門，見吾邦君。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>伏震為踐履，坤為患，乾在外，故脫厄去患。艮為門，乾為福喜，巽為入，坤為吾、為邦，乾為君。○福，依宋元本，汲古作臨。</p><h3 id="謙之同人" tabindex="-1">謙之同人 <a class="header-anchor" href="#謙之同人" aria-label="Permalink to “謙之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>宮商既和，聲音相隨。驪駒在門，主君以歡。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。震為樂，故曰宮商、曰聲音。震為隨、為馬，坤為門，震為主、為君、為歡，又震為行。驪駒，為送行之詩。</p><h3 id="謙之大有" tabindex="-1">謙之大有 <a class="header-anchor" href="#謙之大有" aria-label="Permalink to “謙之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>天地配享，六位光明。陰陽順敘，以成厥功。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《震》。</p><h3 id="謙之謙" tabindex="-1">謙之謙 <a class="header-anchor" href="#謙之謙" aria-label="Permalink to “謙之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>王喬無病，狗頭不痛。亡跛失履，乏我徒從。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為壽，故曰王喬。王喬，古仙人。坎為病，震樂故無病。艮為狗，坎為首、為痛，震為履，坎蹇故跛。坤為我。○狗，依汲古，宋元本作苟。跛，依汲古，宋元本作破。亡疑為足之訛。震足坎蹇，故曰足跛。</p><h3 id="謙之豫" tabindex="-1">謙之豫 <a class="header-anchor" href="#謙之豫" aria-label="Permalink to “謙之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>江河淮海，天之奧府。眾利所聚，可以饒有，樂我君子。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《坤》。</p><h3 id="謙之隨" tabindex="-1">謙之隨 <a class="header-anchor" href="#謙之隨" aria-label="Permalink to “謙之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>雙鳥俱飛，欲歸稻池。徑涉萑澤，為矢所射，傷我胸臆。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《旅》。○萑，依《屯》之《旅》校，宋元本作雚，汲古作藿，皆非。</p><h3 id="謙之蠱" tabindex="-1">謙之蠱 <a class="header-anchor" href="#謙之蠱" aria-label="Permalink to “謙之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>伯仲叔季，日暮寢寐。裸卧失明，喪我貝囊，銜卻道傍。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震為伯，大坎為仲，艮為叔季，坎為莫、為寢寐，艮為身、為裸、為卧、為明，兌昧故失明，兌毀折故曰喪。艮為貝，震為道、為囊。○伯，從汲古，宋元本作留。裸，汲古作裸，宋元本作羸，由汲古證之可見宋元本原作裸。羸裸同，故從之。明、喪、貝，從汲古，宋元本作限、虐、具，非。卻，汲古作缷，依宋元本。</p><h3 id="謙之臨" tabindex="-1">謙之臨 <a class="header-anchor" href="#謙之臨" aria-label="Permalink to “謙之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>受終文祖，承衰復起。以義自閑，雖苦無咎。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>坤為文，伏艮為終、為祖，故受終文祖。坤為衰，震為起，坤為義、為咎，震樂故無咎。○閑，依汲古，宋元本作閉。</p><h3 id="謙之觀" tabindex="-1">謙之觀 <a class="header-anchor" href="#謙之觀" aria-label="Permalink to “謙之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>據鬥運樞，順天無憂，與樂並居。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《益》之《節》。</p><h3 id="謙之噬嗑" tabindex="-1">謙之噬嗑 <a class="header-anchor" href="#謙之噬嗑" aria-label="Permalink to “謙之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>周師伐紂，戰於牧野。甲子平旦，天下悅喜。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為周、為伐，坎眾為師，離為惡人，故曰紂。艮為城。《尚書》註：牧野城，周武王所築。震為旦、為子，艮為甲，故曰甲子。坎為平，故曰平旦。艮為天，震為下、為樂。《周書》：&quot;武王伐紂，甲子昧爽，王朝至於商郊牧野&quot;，林所本也。</p><h3 id="謙之賁" tabindex="-1">謙之賁 <a class="header-anchor" href="#謙之賁" aria-label="Permalink to “謙之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>十雌百雛，常與母俱。抱雞搏虎，誰敢害諸。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>通《困》。巽為雌，兌為雛，數十故曰十雌。震為百、為子，故曰百雛。巽為母、為雞，艮為虎、為抱，故曰抱雞搏虎。○百，元本作伯，從宋本、汲古。諸，依宋元本，汲古作者，與俱不協。○巽母證。</p><h3 id="謙之剝" tabindex="-1">謙之剝 <a class="header-anchor" href="#謙之剝" aria-label="Permalink to “謙之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>桀跖並處，人民愁苦。擁兵荷糧，戰於齊魯。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>此用《謙》象。坤為惡，故曰桀。坎為盜，故曰跖。震為人民，坎為愁苦，艮為兵，震為糧，艮手為擁，艮背為荷。震為戰，伏兌為魯，巽為齊，故曰齊魯。</p><h3 id="謙之復" tabindex="-1">謙之復 <a class="header-anchor" href="#謙之復" aria-label="Permalink to “謙之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>南山昊天，刺政閔身。疾悲無辜，背憎為仇。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《臨》。</p><h3 id="謙之無妄" tabindex="-1">謙之無妄 <a class="header-anchor" href="#謙之無妄" aria-label="Permalink to “謙之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>百川朝海，流行不止。道雖遼遠，無不到者。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>乾為海、為百川。震為行、為道、為遠、為至，故無不到。</p><h3 id="謙之大畜" tabindex="-1">謙之大畜 <a class="header-anchor" href="#謙之大畜" aria-label="Permalink to “謙之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>目不可合，憂來搖足。悚惕危懼，去其邦域。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>大離故目不合。震為足、為搖，乾為憂、為危惕。艮為邦域，艮在外故曰去。○危，依汲古，宋元本作為。</p><h3 id="謙之頤" tabindex="-1">謙之頤 <a class="header-anchor" href="#謙之頤" aria-label="Permalink to “謙之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>鳥升鵲舉，照臨東海。尨降庭堅，為陶叔後。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>封於英六，履福綏厚。詳《需》之《大畜》。</p><h3 id="謙之大過" tabindex="-1">謙之大過 <a class="header-anchor" href="#謙之大過" aria-label="Permalink to “謙之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>北方多棗，橘柚所聚。何囊載黍，盈我筐筥。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。坤為北，艮為棗、為橘柚，正反艮故曰聚，坤亦為聚也。坤為囊，艮為何，震為黍、為載、為筐筥。</p><h3 id="謙之坎" tabindex="-1">謙之坎 <a class="header-anchor" href="#謙之坎" aria-label="Permalink to “謙之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>懸貆素飡，食非其任。失望遠民，實勞我心。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>《詩小雅伐檀篇》：&quot;胡瞻爾庭有懸貆兮？不素餐兮？&quot;互艮為貆，震為素、為餐，坎為食，伏巽為繩，故曰懸。艮為望，坎失，故曰失望。坎為民、為勞、為心。○貆，宋元本作狟。飡，汲古作餐，依宋元本。食非其任，言不稱職也。</p><h3 id="謙之離" tabindex="-1">謙之離 <a class="header-anchor" href="#謙之離" aria-label="Permalink to “謙之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>羔羊皮革，君子朝服。輔政扶德，以合萬國。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>詳《晉》之《臨》。</p><h3 id="謙之咸" tabindex="-1">謙之咸 <a class="header-anchor" href="#謙之咸" aria-label="Permalink to “謙之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>齊魯爭言，戰於龍門。構怨致禍，三世不安。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《大畜》。○世，依宋元本，汲古作三歲。</p><h3 id="謙之恒" tabindex="-1">謙之恒 <a class="header-anchor" href="#謙之恒" aria-label="Permalink to “謙之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>久陰霖雨，塗行泥潦。商人休止，市空無有。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>互大坎故曰陰、曰霖雨、曰泥潦。震為大塗、為行、為商人，坎陷故休止。巽為市，兌毀故空無所有。○市空無有，依汲古，宋元本作市無所有。</p><h3 id="謙之遯" tabindex="-1">謙之遯 <a class="header-anchor" href="#謙之遯" aria-label="Permalink to “謙之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>桃雀竊脂，巢於小枝。搖動不安，為風所吹。心寒慄慄，常憂殆危。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥故曰桃雀。竊脂，《詩大雅》：&quot;肇允彼桃蟲&quot;，《傳》&quot;桃蟲，鷦鷯也&quot;。鷦鷯，即桃雀。《爾雅》：&quot;桑扈、竊脂，皆小鳥&quot;，艮為小也。艮為巢、為枝，巽風進退故動搖。乾為寒、為惕，故曰慄慄、曰危殆。○巢，依宋元本，汲古作來，非。心寒，依《旅》之《晉》校。</p><h3 id="謙之大壯" tabindex="-1">謙之大壯 <a class="header-anchor" href="#謙之大壯" aria-label="Permalink to “謙之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>防患備災，凶禍不來，雖困無災。通《觀》。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>坤為患、為災，艮為防，坤為凶禍，坤閉故困。○均依汲古，宋元本禍作惡，無災作無憂，多&quot;未獲安休&quot;四字。</p><h3 id="謙之晉" tabindex="-1">謙之晉 <a class="header-anchor" href="#謙之晉" aria-label="Permalink to “謙之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>引頸絕糧，與母異門。不見所歡，孰與共言。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮為頸，震為糧，震覆坤輿閉故絕糧。坤為母、為門，艮亦為門。坤西南、艮東北，故曰異門。震為歡、為言，震覆坤閉，故不見所歡，故無與共言。○頸，依汲古，宋元本作順，非。</p><h3 id="謙之明夷" tabindex="-1">謙之明夷 <a class="header-anchor" href="#謙之明夷" aria-label="Permalink to “謙之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>曄喝ズ＃藏於枯里。街巷褊隘，不得自在。南北極遠，渴餒成疾。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坤為魚，故曰曄骸？參海，坤在外，故曰去海。坤為里、為藏，離為枯、為巷。坎為褊隘，離南坎北，坎為疾，離為渴餒。○褊，汲古作偏，從宋元本。極遠，汲古作無極，從宋元本。</p><h3 id="謙之家人" tabindex="-1">謙之家人 <a class="header-anchor" href="#謙之家人" aria-label="Permalink to “謙之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>恭寬信敏，功加四海。闢去不詳，喜來從母。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>坎為信，巽為母，伏震為喜。</p><h3 id="謙之睽" tabindex="-1">謙之睽 <a class="header-anchor" href="#謙之睽" aria-label="Permalink to “謙之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>歲飢無年，虐政害民。乾溪驪山，秦楚結怨。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>離虛故飢。坎為眾、為民，兌毀折故曰虐、曰害。坎為溪，離火故曰乾溪。坎為馬，伏艮為山，故曰驪山。兌西故曰秦，離南故曰楚。楚靈王死於乾溪，秦始皇葬驪山，故曰秦楚結怨。坎為怨也。</p><h3 id="謙之蹇" tabindex="-1">謙之蹇 <a class="header-anchor" href="#謙之蹇" aria-label="Permalink to “謙之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>右目無瞳，偏視寡明。十步之外，不知何公。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此用《謙》象。伏兌為右，艮離目不全故無瞳，故偏視，坎黑故寡明。坤數十，震為公、為步，正反震，故不知何公。</p><h3 id="謙之解" tabindex="-1">謙之解 <a class="header-anchor" href="#謙之解" aria-label="Permalink to “謙之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>蜩螗歡喜，草木嘉茂。百果蕃熾，日益庶有。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>此用《謙》象。震為鳴，伏巽故曰蜩螗。《豳風》註：蜩，蟬也。宋曰螗。震為歡喜，《詩大雅》：&quot;如蜩如螗，如沸如羹&quot;，箋雲：言飲酒歡呼之聲似蜩螗之鳴，茲曰歡喜，用詩意也。震為草木、為嘉茂、為百、為蕃熾。艮為果、為日。○果、庶，從汲古，宋元作菓、作多。</p><h3 id="謙之損" tabindex="-1">謙之損 <a class="header-anchor" href="#謙之損" aria-label="Permalink to “謙之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>常德自如，安坐無尤。幸入貴鄉，到老安榮。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>艮止故曰常德、曰安坐。艮為鄉、為貴，坤為老，震為榮。○幸入，宋本作華萃，元本作華入，依汲古。○艮貴可解《易》。</p><h3 id="謙之益" tabindex="-1">謙之益 <a class="header-anchor" href="#謙之益" aria-label="Permalink to “謙之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>狡兔趯趯，良犬逐咋。雄雌爰爰，為鷹所獲。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為兔、為行，互艮為大。震為逐，震口為咋、為雄，巽為雌，爰爰，行貌。艮為鷹、為獲，《詩小雅》：&quot;躍躍毚兔，遇犬獲之&quot;，《釋文》：&quot;躍，他厯反，與趯同&quot;，又《王風》：&quot;有兔爰爰&quot;，《傳》：&quot;爰爰，行緩也&quot;。○雄雌爰爰，依《未濟》之《師》校，各本作雄雉受害，非。</p><h3 id="謙之夬" tabindex="-1">謙之夬 <a class="header-anchor" href="#謙之夬" aria-label="Permalink to “謙之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>春桃生花，季女宜家。受福多年，男為邦君。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《坤》。</p><h3 id="謙之姤" tabindex="-1">謙之姤 <a class="header-anchor" href="#謙之姤" aria-label="Permalink to “謙之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>山石朽弊，消崩墮落。上下離心，君受其祟。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>乾為山、為石，巽為朽弊、為消崩墮落。乾為君，陰消陽，故曰受祟。○消墮，從汲古，宋元本作稍墮。</p><h3 id="謙之萃" tabindex="-1">謙之萃 <a class="header-anchor" href="#謙之萃" aria-label="Permalink to “謙之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>水壞我里，東流為海。龜鳧歡嘩，不睹我家。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《兌》。</p><h3 id="謙之升" tabindex="-1">謙之升 <a class="header-anchor" href="#謙之升" aria-label="Permalink to “謙之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>七竅龍身，造易八元。法天則地，順時施恩，富貴長存。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>元本註：聖人心有七竅，伏羲蛇身。《左傳》：&quot;高辛氏有才子八人，天下謂之八元&quot;，互兌為穴、為竅，數七，故曰七竅。震為龍，坤為身，故曰龍身。坤數八，又為地，伏乾為天，故曰法天則地。震為時，坤順，故曰順時。伏乾為富貴。翟雲升謂伏義龍身，八元即八卦。○易，汲古作化，施恩作施行，均從宋元本。</p><h3 id="謙之困" tabindex="-1">謙之困 <a class="header-anchor" href="#謙之困" aria-label="Permalink to “謙之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>四夷慕德，來興我國。文君陟降，同受福德。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>坎為夷，伏震，卦數四，故曰四夷。坎為慕，伏艮為國。震為君，互離故曰文君。正反震，故曰陟降、曰福德。○同福，依宋元本，汲古作合其，《詩大雅》：&quot;文王陟降&quot;，文君即文王。</p><h3 id="謙之井" tabindex="-1">謙之井 <a class="header-anchor" href="#謙之井" aria-label="Permalink to “謙之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>華首山頭，仙道所游。利以居止，長無咎憂。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>伏艮為山，坎為首，兌為華，故曰華首。艮為壽，故曰仙道。伏震為游，巽為利、為長，艮為居止，坎為憂。</p><h3 id="謙之革" tabindex="-1">謙之革 <a class="header-anchor" href="#謙之革" aria-label="Permalink to “謙之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>鸇鳩徙巢，西至平州。遭逢雷雹，損我葦蘆。家室饑寒，思吾故初。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。艮為鸇鳩、為巢，震行，故曰徙巢。坎為平、為西、為冰雹，震為雷、為葦蘆，兌毀坤我，艮為家室，坤為饑寒。○損，從汲古，宋元本作闢。</p><h3 id="謙之鼎" tabindex="-1">謙之鼎 <a class="header-anchor" href="#謙之鼎" aria-label="Permalink to “謙之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>狗無前足，陰謀叛北，為身害賊。詳《小畜》之《明夷》。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>艮為狗，初二半艮，無初爻，故無前足。震為足，震伏亦無。○北，依汲古，宋元本作背。《說文》：&quot;背，乖也&quot;。二人相背，《史記魯仲連傳》：&quot;士無反北之心&quot;，背乃妄人所改。</p><h3 id="謙之震" tabindex="-1">謙之震 <a class="header-anchor" href="#謙之震" aria-label="Permalink to “謙之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>陽孤亢極，多所恨惑。車傾蓋亡，身常驚惶。乃得其願，雌雄相從。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《屯》。○從，依宋元本，汲古作存，乃音訛。</p><h3 id="謙之艮" tabindex="-1">謙之艮 <a class="header-anchor" href="#謙之艮" aria-label="Permalink to “謙之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>空槽註器，豚彘不到。張弓祝雞，雄鳩飛去。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>鳩皆作父，依《師》之《旅》校。祝，呼也。</p><h3 id="謙之漸" tabindex="-1">謙之漸 <a class="header-anchor" href="#謙之漸" aria-label="Permalink to “謙之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>長夜短日，陰為陽賊。萬物空枯，藏於北陸。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>巽為長，坎為夜，離日坎隱，故短日。坎為賊，北方陰，離日為陽，陽為坎陰所蔽，故曰陰為陽賊。巽為草莽、為萬物，離虛故空枯。坎為藏、為北，艮為道，故曰北陸。冬日行北陸。</p><h3 id="謙之歸妹" tabindex="-1">謙之歸妹 <a class="header-anchor" href="#謙之歸妹" aria-label="Permalink to “謙之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>爪牙之士，怨毒祈父。轉憂於已，傷不及母。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>兌為爪牙，震為士、為父，故曰祈父。坎為怨毒、為憂，巽為母，巽伏，故傷不及母。《詩小雅祈父》：&quot;予王之爪牙，胡轉於予恤，有母之屍饔&quot;。祈父，司馬也，言司馬令我久役，移憂於已，不及事母，令母主爨也。林全說詩意。○震父巽母證。</p><h3 id="謙之豐" tabindex="-1">謙之豐 <a class="header-anchor" href="#謙之豐" aria-label="Permalink to “謙之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>拜跪請兔，不得臭腐。俛眉銜指，低頭北去。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>伏艮為拜跪，震為兔，震言，故請兔。巽為臭腐，巽伏故不得。艮為眉，坎陷，故俛眉。艮為指，兌口，故銜指。坎為首、為低、為北。多用伏象。○俛，從汲古，宋元本訛輓。眉，依宋元本，汲古作首。低頭，依宋元本，汲古作不得。</p><h3 id="謙之旅" tabindex="-1">謙之旅 <a class="header-anchor" href="#謙之旅" aria-label="Permalink to “謙之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>有莘季女，為夏妃後。貴夫壽子，母字四海。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>巽為草莽、為莘，兌為季女，離為夏，艮貴艮壽，震夫震子，巽為母，兌為海，震卦數四，故曰四海。○夏，從宋元，汲古作王。○巽母可解《易》。</p><h3 id="謙之巽" tabindex="-1">謙之巽 <a class="header-anchor" href="#謙之巽" aria-label="Permalink to “謙之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>季姬躊躇，待孟城隅。終日至暮，不見齊侯。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《隨》。○季姬、暮，從宋元本，汲古作薑、作旦，非。</p><h3 id="謙之兌" tabindex="-1">謙之兌 <a class="header-anchor" href="#謙之兌" aria-label="Permalink to “謙之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>邯鄲反言，父兄生患。涉叔憂恨，卒死不還。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《睽》。叔，從宋元本，汲古作此，非。叔，吳廣字也。憂恨，從汲古，宋元作援殂。卒，從汲古，宋元作一。</p><h3 id="謙之渙" tabindex="-1">謙之渙 <a class="header-anchor" href="#謙之渙" aria-label="Permalink to “謙之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>逐鹿山巔，利去我西。維邪南北，所求不得。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>艮為鹿、為山、為巔，震為逐，巽為利，坎為西，震為言，故曰維邪。維邪，呼聲。震為南，坎為北，艮為求。○所求不得，依汲古，宋元作利無不得。</p><h3 id="謙之節" tabindex="-1">謙之節 <a class="header-anchor" href="#謙之節" aria-label="Permalink to “謙之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>穿鼻系株，為虎所拘。王母祝福，禍不成災，突然自來。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為鼻，坎為穿，伏巽為系，震為株，言既穿其鼻又繫於木也。艮為虎、為拘，震為王，伏巽為母，故曰王母。震為福、為祝，坎為禍、為災。○株，汲古作珠，依宋元本。福，依汲古，宋元本訛榴。</p><h3 id="謙之中孚" tabindex="-1">謙之中孚 <a class="header-anchor" href="#謙之中孚" aria-label="Permalink to “謙之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>虎豹熊羆，游戲山谷。君子仁賢，皆得所欲。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>艮為虎豹熊羆、為山谷。《易井九二》&quot;井谷射鮒&quot;，以伏艮為谷也。震為游，艮為君子、為仁賢。○皆，汲古作亦，從宋元本。</p><h3 id="謙之小過" tabindex="-1">謙之小過 <a class="header-anchor" href="#謙之小過" aria-label="Permalink to “謙之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>梅李冬實，國多盜賊。擾亂並作，王不得制。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《師》。此以正反巽為盜賊，故曰多。</p><h3 id="謙之既濟" tabindex="-1">謙之既濟 <a class="header-anchor" href="#謙之既濟" aria-label="Permalink to “謙之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>望幸不到，文章未就。王子逐兔，犬踦不得。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《謙》象。艮為望，坤為文章，震為王、為子、為逐、為兔，艮為犬，坎為踦。○王子，依宋元本，汲古作三。</p><h3 id="謙之未濟" tabindex="-1">謙之未濟 <a class="header-anchor" href="#謙之未濟" aria-label="Permalink to “謙之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>千柱百梁，終不傾僵。仁智輔聖，周宗寧康。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>此用《謙》象。坤為千、百，艮為柱，坎為極、為梁，震仁，坎智，坎聖，震為周。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
